insert into public.objeciones (id, categoria, objecion, variantes, detras, preguntas, di_mejor, no_decir, revisar_legal, fuentes) values
  ('OBJ-01', 'precio', 'Está muy caro', array['Está muy caro', 'Uf, con ese precio no la armamos']::text[], 'No ve el valor; compara servicios distintos; busca descuento; no tiene presupuesto (otra objeción)', array['¿Caro comparado con qué: con lo que pagan hoy o con otra propuesta?', '¿Contra qué cifra lo compara: renta mensual o costo total a 36 meses?', '¿Cuánto les cuesta una hora sin enlace o sin sistemas?', 'Si el precio fuera el adecuado, ¿la solución resuelve lo que necesitan?']::text[], 'Prefiero ajustar el alcance que bajarle a la calidad. Veamos qué es indispensable.', array['Ofrecer descuento de inmediato', 'Es que la calidad se paga', 'No, no está caro']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://blog.hubspot.es/sales/manejo-de-objeciones-ventas', 'https://www.appvizer.es/revista/relacion-cliente/software-crm/objeciones-de-ventas', 'https://www.rainsalestraining.com/sales-training-programs/sales-negotiation', 'https://www.gong.io/blog/sales-reps-talk-pricing/']::text[]),
  ('OBJ-02', 'precio', 'No tenemos presupuesto', array['No tenemos presupuesto', 'Ahorita no hay lana para eso', 'Finanzas congeló gastos']::text[], 'El presupuesto llega en otro momento; falta prioridad; el interlocutor no controla el presupuesto', array['¿Cuándo arman el presupuesto del próximo ejercicio?', '¿Esto saldría del presupuesto de TI, de operaciones o de otra área?', '¿Les serviría arrancar por fases o en renta mensual?', '¿Qué tendría que demostrar para que entre en la planeación?']::text[], 'Muchas veces no falta presupuesto sino caso de negocio. ¿Lo armamos con sus números?', array['Le llamo cuando tenga presupuesto sin fecha', 'inventar urgencia']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://blog.hubspot.es/sales/manejo-de-objeciones-ventas', 'https://www.appvizer.es/revista/relacion-cliente/software-crm/objeciones-de-ventas', 'https://www.rainsalestraining.com/sales-training-programs/sales-negotiation', 'https://www.gong.io/blog/sales-reps-talk-pricing/']::text[]),
  ('OBJ-03', 'precio', 'La competencia me lo da más barato', array['La competencia me lo da más barato', 'Telmex me lo deja más barato', 'En AWS directo me sale menos']::text[], 'Necesita justificar la elección ante compras; las propuestas no son comparables; usa la cotización para negociar', array['¿Las propuestas incluyen el mismo SLA, ancho de banda y tiempo de respuesta?', 'Aparte del precio, ¿qué le gustó de la otra propuesta?', 'Si quedaran iguales en precio, ¿con cuál se quedaría?']::text[], 'Tiene sentido comparar. Asegurémonos de comparar lo mismo: SLA, soporte, redundancia y migración.', array['Hablar mal del competidor', 'igualar el precio sin preguntar']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://blog.hubspot.es/sales/manejo-de-objeciones-ventas', 'https://www.appvizer.es/revista/relacion-cliente/software-crm/objeciones-de-ventas', 'https://www.rainsalestraining.com/sales-training-programs/sales-negotiation', 'https://www.gong.io/blog/sales-reps-talk-pricing/']::text[]),
  ('OBJ-04', 'precio', '¿Me haces descuento?', array['¿Me haces descuento?', 'Compras me pide un mejor número']::text[], 'Costumbre de negociación (táctica común en B2B); requisito de compras; prueba de si el precio tiene aire', array['¿El descuento es por presupuesto, por una comparación o por política de compras?', 'Aparte del precio, ¿todo lo demás está bien?', 'Si ajustamos el precio, ¿podríamos extender el plazo o sumar sitios?']::text[], 'Puedo revisarlo, pero cualquier ajuste va ligado a algo: plazo, volumen o fecha de firma.', array['Dar descuento sin contrapartida', 'descuentos escalonados', 'Ese es el precio y ya']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://blog.hubspot.es/sales/manejo-de-objeciones-ventas', 'https://www.appvizer.es/revista/relacion-cliente/software-crm/objeciones-de-ventas', 'https://www.rainsalestraining.com/sales-training-programs/sales-negotiation', 'https://www.gong.io/blog/sales-reps-talk-pricing/']::text[]),
  ('OBJ-05', 'proveedor', 'Ya tenemos proveedor', array['Ya tenemos proveedor', 'Eso ya lo tenemos cubierto']::text[], 'Reflejo para cortar la llamada; costo y riesgo de cambiar; no ve razón para cambiar', array['¿Con quién trabajan hoy y desde hace cuánto?', 'Si pudiera mejorar algo del servicio actual, ¿qué sería?', '¿Tienen un segundo enlace o todo depende de un solo proveedor?', '¿Qué tendría que pasar para considerar una segunda opción?']::text[], 'No le propongo cambiar todo; muchos clientes nos usan como respaldo o segunda opinión.', array['Atacar al proveedor actual', 'Nosotros somos mejores', 'colgar sin preguntar cuándo vence el contrato']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://close.com/blog/sales-objections', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://redriver.com/managed-services/managed-it-services-vs-in-house-it', 'https://www.smartlead.ai/blog/cold-call-objection-handling']::text[]),
  ('OBJ-06', 'proveedor', 'Estamos contentos con Telmex / Totalplay / AWS directo', array['Estamos contentos con Telmex / Totalplay / AWS directo']::text[], 'Satisfacción real; miedo al riesgo de migrar; relación personal con su ejecutivo', array['¿Qué es lo que más valoran del servicio actual?', '¿Qué pasaría con la operación si ese único enlace se cae un día?', 'Si pudiera agregar algo sin cambiar de proveedor, ¿qué sería?']::text[], 'No se trata de reemplazar a nadie, sino de reducir la dependencia de un solo proveedor.', array['No saben lo que se están perdiendo', 'criticar la marca']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://close.com/blog/sales-objections', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://redriver.com/managed-services/managed-it-services-vs-in-house-it', 'https://www.smartlead.ai/blog/cold-call-objection-handling']::text[]),
  ('OBJ-07', 'proveedor', 'Nuestro integrador lo hace', array['Nuestro integrador lo hace', 'Lo lleva nuestra empresa de sistemas']::text[], 'Lealtad o dependencia con el integrador; no quiere coordinar a varios actores', array['¿El integrador recomienda el proveedor de conectividad o ustedes lo eligen?', '¿Me autoriza a contactarlo para armar la propuesta en conjunto?', '¿Quién decide al final: ustedes o el integrador?']::text[], 'Trabajamos con integradores, no contra ellos. Podemos ser el proveedor detrás de su socio.', array['Puentear al integrador sin permiso', 'Con nosotros ya no lo necesitaría']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://close.com/blog/sales-objections', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://redriver.com/managed-services/managed-it-services-vs-in-house-it', 'https://www.smartlead.ai/blog/cold-call-objection-handling']::text[]),
  ('OBJ-08', 'proveedor', 'Lo hacemos nosotros mismos', array['Lo hacemos nosotros mismos', 'Tenemos nuestro propio site']::text[], 'Orgullo o empleo del equipo interno (el interlocutor puede ser parte de ese equipo); control', array['¿Qué parte del tiempo del equipo se va en operación?', '¿Cómo cubren guardias nocturnas y vacaciones?', '¿Qué proyectos se quedan pendientes por apagar fuegos?']::text[], 'Su equipo conoce el negocio mejor que nadie; la idea es quitarle lo operativo.', array['Sale más barato que su gente', 'insinuar que el equipo no es capaz']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://close.com/blog/sales-objections', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://redriver.com/managed-services/managed-it-services-vs-in-house-it', 'https://www.smartlead.ai/blog/cold-call-objection-handling']::text[]),
  ('OBJ-09', 'timing', 'No es el momento', array['No es el momento', 'Tenemos muchas cosas encima']::text[], 'Prioridades que compiten; falta de urgencia; rechazo educado', array['¿Qué proyectos tienen prioridad hoy?', '¿Qué les cuesta seguir igual seis meses más?', '¿Hay alguna fecha clave: renovación, apertura de sucursal, auditoría?']::text[], 'No le pido decidir hoy, solo dejar claro cuánto cuesta esperar.', array['Va a ser rápido, se lo prometo', 'aceptar más adelante sin fecha']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/']::text[]),
  ('OBJ-10', 'timing', 'Llámame el próximo trimestre', array['Llámame el próximo trimestre', 'Después de Semana Santa lo vemos']::text[], 'Evasiva (Gong la clasifica así) o un evento real', array['¿Qué va a cambiar el próximo trimestre que hoy no está?', '¿Agendamos desde ahora una fecha tentativa?', '¿Qué información le sería útil tener lista para entonces?']::text[], 'Con gusto. Para que esa llamada valga la pena, ¿qué necesita saber de nosotros?', array['Claro, yo le marco sin fecha ni motivo']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/']::text[]),
  ('OBJ-11', 'timing', 'Estamos en cierre de año', array['Estamos en cierre de año', 'Estamos en auditoría']::text[], 'Congelamiento real de compras o de cambios en TI; presupuesto agotado', array['¿Su cierre es en diciembre o tienen otro año fiscal?', '¿Cuándo arrancan la planeación del próximo año?', '¿Les convendría firmar ahora e implementar después del congelamiento?']::text[], 'Si lo dejamos planeado, entra en el presupuesto nuevo sin carreras.', array['Forzar una implementación durante el congelamiento']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/']::text[]),
  ('OBJ-12', 'evasiva', 'Mándame información por correo', array['Mándame información por correo', 'Pásame algo por escrito']::text[], 'Forma educada de colgar; interés real sin tiempo; quiere algo para circular internamente', array['Claro. ¿Qué tema específico quiere que cubra?', '¿Lo revisaría usted o lo compartiría con alguien más?', '¿Se lo mando y lo revisamos el jueves a las 10?']::text[], 'Para no mandarle un folleto genérico, deme dos datos y le envío solo lo que aplica.', array['Mandar un PDF genérico sin siguiente paso', '¿Lo va a leer?']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://www.gong.io/blog/cold-call-objections/', 'https://www.gong.io/resources/labs/we-found-the-top-objections-across-300m-cold-calls-heres-how-to-handle-them-all/']::text[]),
  ('OBJ-13', 'evasiva', 'No me interesa', array['No me interesa', 'No necesitamos nada']::text[], 'Reflejo, porque aún no sabe qué se le ofrece; llamadas repetidas de otros proveedores', array['¿Es porque ya lo tienen resuelto o porque no es prioridad?', '¿Le hago una sola pregunta y, si no aplica, cuelgo?', '¿Cuándo vence su contrato actual de conectividad?']::text[], 'Sí, es una llamada en frío. ¿Me da 30 segundos para que decida si cuelga?', array['¿Por qué no le interesa?', 'seguir el pitch como si nada']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://www.gong.io/blog/cold-call-objections/', 'https://www.gong.io/resources/labs/we-found-the-top-objections-across-300m-cold-calls-heres-how-to-handle-them-all/']::text[]),
  ('OBJ-14', 'evasiva', 'Estoy ocupado', array['Estoy ocupado', 'Ando en junta', 'Ando manejando']::text[], 'No puede de verdad, o es evasiva', array['¿Le marco hoy en la tarde o mañana temprano?', '¿Le funciona el martes o el jueves, 15 minutos?', '¿Le mando un WhatsApp con una línea de contexto?']::text[], 'Le tomo 20 segundos para decirle por qué le llamo y usted decide si agendamos.', array['Abrir con ¿Lo agarro en mal momento?', 'seguir hablando']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://www.gong.io/blog/cold-call-objections/', 'https://www.gong.io/resources/labs/we-found-the-top-objections-across-300m-cold-calls-heres-how-to-handle-them-all/']::text[]),
  ('OBJ-15', 'evasiva', 'Eres el cuarto que me llama esta semana', array['Eres el cuarto que me llama esta semana']::text[], 'Saturación de llamadas', array['¿Me da 30 segundos y, si no aplica, cuelgo?', '¿Cuándo vence su contrato, para no llamarle antes de tiempo?']::text[], 'Decir cuánto dura la llamada, de dónde salió el número y un hecho fechado y verificable', array['Fingir ser distinto a los demás', 'discutir']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://www.gong.io/blog/cold-call-objections/', 'https://www.gong.io/resources/labs/we-found-the-top-objections-across-300m-cold-calls-heres-how-to-handle-them-all/']::text[]),
  ('OBJ-16', 'evasiva', '¿De dónde sacaste mi número?', array['¿De dónde sacaste mi número?']::text[], 'Desconfianza', array['¿Le explico en 20 segundos por qué le llamo?']::text[], 'Explicar la fuente con calma y sin evasivas', array['Evadir o inventar la fuente']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://www.gong.io/blog/cold-call-objections/', 'https://www.gong.io/resources/labs/we-found-the-top-objections-across-300m-cold-calls-heres-how-to-handle-them-all/']::text[]),
  ('OBJ-17', 'autoridad', 'Lo tengo que consultar con mi jefe / TI / compras', array['Lo tengo que consultar con mi jefe / TI / compras', 'Lo subo al comité']::text[], 'No tiene la autoridad final; necesita armar el caso interno; esconde sus propias dudas detrás del jefe', array['¿Quién más participa en la decisión y qué le importa a cada uno?', '¿Qué cree que le va a preguntar su director?', '¿Usted lo recomendaría? ¿Qué duda tiene todavía?', '¿Agendamos 20 minutos con usted y su director juntos?']::text[], 'Para que no le toque defenderlo solo, armemos juntos el caso con los números que le van a pedir.', array['¿Entonces con quién tengo que hablar?', 'saltarse al contacto sin acordarlo']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://spotio.com/blog/how-to-confidently-handle-sales-objections-a-field-tested-action-plan/', 'https://www.gong.io/blog/objection-handling-techniques/']::text[]),
  ('OBJ-18', 'autoridad', 'No soy quien decide', array['No soy quien decide', 'Yo nada más soy el contacto']::text[], 'No es su área de verdad, o es evasiva', array['¿Quién ve los temas de conectividad o nube?', '¿Usted participa en la evaluación aunque no firme?', '¿Me presenta o prefiere que lo contacte mencionándolo?']::text[], 'Su opinión cuenta igual: quien opera el servicio sabe dónde están los problemas.', array['Perder el interés de forma evidente']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://spotio.com/blog/how-to-confidently-handle-sales-objections-a-field-tested-action-plan/', 'https://www.gong.io/blog/objection-handling-techniques/']::text[]),
  ('OBJ-19', 'autoridad', 'Déjame pensarlo', array['Déjame pensarlo']::text[], 'Alguna duda no dicha; ya eligió a otro proveedor', array['Claro. ¿Qué parte le gustaría pensar con más calma?', '¿Hay algo de la propuesta que no le convenció?', '¿Ya decidieron irse con otra opción? Puede decírmelo con confianza.']::text[], 'Resumir lo acordado y proponer una fecha', array['¿Qué hay que pensar? en tono de reproche']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://spotio.com/blog/how-to-confidently-handle-sales-objections-a-field-tested-action-plan/', 'https://www.gong.io/blog/objection-handling-techniques/']::text[]),
  ('OBJ-20', 'contrato', 'Tenemos contrato vigente', array['Tenemos contrato vigente', 'Tenemos plazo forzoso', 'Acabamos de renovar']::text[], 'Bloqueo temporal real; excusa; no conoce las fechas ni las cláusulas', array['¿En qué mes vence y con cuánto aviso hay que cancelar?', '¿Se renueva automáticamente si nadie lo cancela?', 'Si no existiera el contrato, ¿seguirían con el mismo proveedor?', '¿Hay sitios o servicios nuevos fuera de ese contrato?']::text[], 'Entonces no es un no, es una fecha. Preparemos la comparación antes de que cierre la ventana de cancelación.', array['Colgar sin registrar la fecha', 'Se puede salir fácilmente']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://tldv.io/es/blog/objection-handling/']::text[]),
  ('OBJ-21', 'contrato', 'Nos cobran penalización si cambiamos', array['Nos cobran penalización si cambiamos']::text[], 'Costo de cambio; miedo a quedar mal internamente por un costo hundido', array['¿Sabe de cuánto es la penalización y cómo se calcula?', '¿Cuántos meses le quedan al contrato?', '¿Me permite comparar el costo de salir contra el beneficio?']::text[], 'Hagamos la cuenta completa. Si no conviene, se lo digo.', array['Prometer absorber penalizaciones sin aprobación', 'dar asesoría legal']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://tldv.io/es/blog/objection-handling/']::text[]),
  ('OBJ-22', 'contrato', 'No quiero amarrarme a un contrato largo', array['No quiero amarrarme a un contrato largo', '¿Y si no nos funciona?']::text[], 'Miedo a quedar atado a un mal servicio', array['¿Qué plazo le daría tranquilidad?', '¿Le preocupa el costo o quedarse atado si el servicio falla?']::text[], 'Lo justo es que el compromiso vaya en los dos sentidos: si no cumplimos el SLA, que nos cueste a nosotros.', array['Es estándar, todos firman a 36 meses']::text[], false, array['https://close.com/blog/sales-objections', 'https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones', 'https://tldv.io/es/blog/objection-handling/']::text[]),
  ('OBJ-23', 'necesidad', 'No lo necesitamos', array['No lo necesitamos', 'Estamos bien así']::text[], 'No ve el problema o no le duele lo suficiente; status quo', array['¿Cómo resuelven hoy el respaldo entre sucursales?', '¿Qué le quita más tiempo a su equipo de TI?', '¿Qué tanto ha crecido su consumo de nube en el último año?']::text[], 'Puede ser. En empresas similares vemos [insight verificado]; ¿aplica en su caso o no?', array['Todos lo necesitan', 'insistir con funcionalidades']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones']::text[]),
  ('OBJ-24', 'necesidad', 'Nunca nos ha pasado', array['Nunca nos ha pasado', 'Nunca se nos ha caído el internet']::text[], 'Sesgo de optimismo; no ha cuantificado el riesgo', array['Si mañana se cae el enlace cuatro horas, ¿qué se detiene?', '¿Tienen un plan documentado de continuidad?', '¿Cuánto produce la empresa por hora?']::text[], 'Que no haya pasado es buena señal; la pregunta es cuánto cuesta el día que pase.', array['Asustar con catástrofes', 'inventar estadísticas de ataques']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones']::text[]),
  ('OBJ-25', 'necesidad', 'No conozco a Alestra', array['No conozco a Alestra', '¿Son de Telmex o de quién?']::text[], 'Riesgo de elegir a un desconocido; duda sobre respaldo y cobertura', array['¿Qué necesita saber de un proveedor para considerarlo confiable?', '¿Le ayudaría hablar con un cliente de su industria?', '¿En qué ciudades necesitan cobertura?']::text[], 'Le comparto referencias de su sector y usted juzga.', array['Un monólogo de historia corporativa', 'cifras sin verificar']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones']::text[]),
  ('OBJ-26', 'necesidad', 'Tuvimos mala experiencia', array['Tuvimos mala experiencia', 'La última migración fue un desastre', 'Nos quedamos un día sin teléfonos']::text[], 'Miedo a repetir; desconfianza en promesas comerciales; riesgo personal de quien decidió', array['¿Qué pasó exactamente: portabilidad, instalación, soporte o facturación?', '¿Qué tendría que ser diferente esta vez?', '¿Le ayudaría empezar con un sitio piloto?']::text[], 'Con razón la desconfianza. En vez de prometerle, le enseño el plan de migración paso a paso y lo ponemos por escrito.', array['Con nosotros eso no pasa', 'contestar con tarifa en vez de con método']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones']::text[]),
  ('OBJ-27', 'necesidad', 'Su competidor dice que ustedes…', array['Su competidor dice que ustedes…']::text[], 'Duda sembrada por otro proveedor', array['¿Quiere que le muestre el dato?']::text[], 'Decir con calma que no es correcto y hacer una pausa', array['Contraatacar']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones']::text[]),
  ('OBJ-28', 'necesidad', 'Nos están comprando / estamos en reestructura', array['Nos están comprando / estamos en reestructura']::text[], 'Incertidumbre organizacional', array['¿Cuándo esperan que se defina la nueva estructura?', '¿Quién verá TI después del cambio?']::text[], 'Cerrar con profesionalismo y agendar cuándo volver a contactar', array['Presionar']::text[], false, array['https://blog.hubspot.com/sales/handling-common-sales-objections', 'https://challengerinc.com/blog/prospect-theory-drives-sales-experiences/', 'https://giantrocketship.com/blog/top-5-objections-prospects-tell-an-msp-and-what-to-do-about-it', 'https://skipcall.io/es/solutions/operadores-telecomunicaciones']::text[]),
  ('OBJ-29', 'seguridad', '¿Y si nos hackean?', array['¿Y si nos hackean?', '¿Quién responde si se filtra información?']::text[], 'Perder operación, reputación o información; no saber quién responde', array['¿Les ha pasado algún incidente antes? ¿Qué aprendieron?', '¿Qué sería más grave: parar la operación o que se filtre información?', '¿Cuándo probaron restaurar un respaldo por última vez?']::text[], 'Ningún proveedor serio le dice que el riesgo es cero. Revisemos con un especialista cómo se reparten las responsabilidades.', array['Es imposible que los hackeen', 'La nube es 100% segura', 'Nos hacemos responsables de todo']::text[], false, array['https://www.deloitte.com/content/dam/Deloitte/us/Documents/risk/us-risk-aws-ransomware-resiliency-whitepaper.pdf', 'https://static.fortra.com/alert-logic/pdfs/guide/fta-al-key-steps-in-defining-a-shared-responsibility-model-for-aws-gd.pdf', 'https://n2ws.com/blog/aws-cloud/preventing-ransomware-on-aws', 'https://redriver.com/?p=41076', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf']::text[]),
  ('OBJ-30', 'seguridad', 'No queremos nuestros datos en la nube', array['No queremos nuestros datos en la nube', 'Prefiero mis servidores aquí donde los veo']::text[], 'Control y visibilidad; a veces, una restricción regulatoria que no menciona', array['¿Qué datos en particular le preocupa mover?', '¿Hay alguna regla interna o de un regulador que lo limite?', 'Si una parte se quedara en sitio y otra no, ¿le haría sentido?']::text[], 'No todo tiene que irse a la nube. Un especialista revisa con ustedes qué cargas sí convienen.', array['Todos ya se están yendo a la nube', 'Nadie del proveedor puede ver nada']::text[], false, array['https://www.deloitte.com/content/dam/Deloitte/us/Documents/risk/us-risk-aws-ransomware-resiliency-whitepaper.pdf', 'https://static.fortra.com/alert-logic/pdfs/guide/fta-al-key-steps-in-defining-a-shared-responsibility-model-for-aws-gd.pdf', 'https://n2ws.com/blog/aws-cloud/preventing-ransomware-on-aws', 'https://redriver.com/?p=41076', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf']::text[]),
  ('OBJ-31', 'seguridad', '¿Y si nos secuestran la información?', array['¿Y si nos secuestran la información?']::text[], 'Capacidad de recuperarse; tiempo sin operar', array['¿Cuánto tiempo sin sistemas aguanta su operación?', '¿Cuánta información podrían perder: una hora, un día?', '¿Sus respaldos están separados de la red principal?']::text[], 'Platiquemos cómo recuperarse rápido si algo pasa; esos tiempos los define el especialista con ustedes.', array['El respaldo es inmune', 'Se recuperan en X minutos sin validación']::text[], false, array['https://www.deloitte.com/content/dam/Deloitte/us/Documents/risk/us-risk-aws-ransomware-resiliency-whitepaper.pdf', 'https://static.fortra.com/alert-logic/pdfs/guide/fta-al-key-steps-in-defining-a-shared-responsibility-model-for-aws-gd.pdf', 'https://n2ws.com/blog/aws-cloud/preventing-ransomware-on-aws', 'https://redriver.com/?p=41076', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf']::text[]),
  ('OBJ-32', 'regulacion', '¿Esto cumple con la CNBV?', array['¿Esto cumple con la CNBV?', 'Somos SOFOM y la CNBV nos revisa']::text[], null, array['¿Qué tipo de entidad son ante la CNBV?', '¿Esto tocaría procesos críticos u operación con clientes?', '¿Quién lleva cumplimiento o jurídico, para incluirlo en la siguiente reunión?']::text[], 'Los requisitos dependen de su tipo de entidad y de lo que se contrate. Propongo que un especialista los revise con su área de cumplimiento.', array['Cumplimos con la CNBV', 'No necesitan autorización', 'Garantizamos que pasa la auditoría']::text[], true, array['https://www.ey.com/es_mx/technical/tax/boletines-fiscales/nueva-ley-federal-proteccion-datos-personal-posesion-particulares', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPDPPP.pdf', 'https://www.littler.com/es/news-analysis/asap/mexico-tiene-nueva-ley-en-materia-de-proteccion-de-datos-personales', 'https://aws.amazon.com/financial-services/security-compliance/compliance-center/mx', 'https://www.ixopay.com/reports-and-guides/ixopay-pci-dss-v401-shared-responsibility-matrix', 'https://services.google.com/fh/files/misc/gcp_pci_dss_v4_responsibility_matrix.pdf']::text[]),
  ('OBJ-33', 'regulacion', '¿Y la ley de datos personales?', array['¿Y la ley de datos personales?', 'Antes era el INAI, ¿ahora quién?']::text[], null, array['¿Qué datos personales manejarían: clientes, empleados, pacientes?', '¿Su aviso de privacidad ya contempla proveedores tecnológicos?', '¿Les gustaría que su área legal revise el contrato de tratamiento de datos?']::text[], 'La nueva ley está vigente desde marzo de 2025 y la autoridad es la Secretaría Anticorrupción y Buen Gobierno. Cómo les aplica lo revisa su área legal.', array['Con nosotros ya cumplen la ley', 'El INAI nos aprobó', 'cualquier cifra de multas']::text[], true, array['https://www.ey.com/es_mx/technical/tax/boletines-fiscales/nueva-ley-federal-proteccion-datos-personal-posesion-particulares', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPDPPP.pdf', 'https://www.littler.com/es/news-analysis/asap/mexico-tiene-nueva-ley-en-materia-de-proteccion-de-datos-personales', 'https://aws.amazon.com/financial-services/security-compliance/compliance-center/mx', 'https://www.ixopay.com/reports-and-guides/ixopay-pci-dss-v401-shared-responsibility-matrix', 'https://services.google.com/fh/files/misc/gcp_pci_dss_v4_responsibility_matrix.pdf']::text[]),
  ('OBJ-34', 'regulacion', 'Manejamos expedientes de pacientes', array['Manejamos expedientes de pacientes']::text[], null, array['¿Guardaría expedientes clínicos o solo datos administrativos?', '¿Quién valida la normatividad en la clínica?']::text[], 'Los datos de salud tienen reglas especiales; un especialista revisa con su responsable normativo qué aplica.', array['Esto cumple la NOM-024 sin una certificación documentada']::text[], true, array['https://www.ey.com/es_mx/technical/tax/boletines-fiscales/nueva-ley-federal-proteccion-datos-personal-posesion-particulares', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPDPPP.pdf', 'https://www.littler.com/es/news-analysis/asap/mexico-tiene-nueva-ley-en-materia-de-proteccion-de-datos-personales', 'https://aws.amazon.com/financial-services/security-compliance/compliance-center/mx', 'https://www.ixopay.com/reports-and-guides/ixopay-pci-dss-v401-shared-responsibility-matrix', 'https://services.google.com/fh/files/misc/gcp_pci_dss_v4_responsibility_matrix.pdf']::text[]),
  ('OBJ-35', 'regulacion', 'Cobramos con tarjeta, ¿esto es PCI?', array['Cobramos con tarjeta, ¿esto es PCI?']::text[], null, array['¿Guardan, procesan o solo transmiten datos de tarjeta?', '¿Quién llena hoy su cuestionario PCI?']::text[], 'Su cumplimiento depende de cómo use el servicio. Le compartimos la matriz de responsabilidades.', array['Con esto ya son PCI compliant']::text[], true, array['https://www.ey.com/es_mx/technical/tax/boletines-fiscales/nueva-ley-federal-proteccion-datos-personal-posesion-particulares', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPDPPP.pdf', 'https://www.littler.com/es/news-analysis/asap/mexico-tiene-nueva-ley-en-materia-de-proteccion-de-datos-personales', 'https://aws.amazon.com/financial-services/security-compliance/compliance-center/mx', 'https://www.ixopay.com/reports-and-guides/ixopay-pci-dss-v401-shared-responsibility-matrix', 'https://services.google.com/fh/files/misc/gcp_pci_dss_v4_responsibility_matrix.pdf']::text[]),
  ('OBJ-36', 'regulacion', 'El SAT nos pide guardar todo cinco años', array['El SAT nos pide guardar todo cinco años', '¿Si cancelo, pierdo mis XML?']::text[], null, array['¿Cuánto tiempo les pide su contador conservarla?', 'Si terminaran el contrato, ¿cómo necesitarían recibir la información?']::text[], 'Los plazos los define su contador; lo que revisamos es que puedan exportar y conservar su información.', array['Cumplimos con el SAT por ustedes', 'Con cinco años basta siempre']::text[], true, array['https://www.ey.com/es_mx/technical/tax/boletines-fiscales/nueva-ley-federal-proteccion-datos-personal-posesion-particulares', 'https://www.diputados.gob.mx/LeyesBiblio/pdf/LFPDPPP.pdf', 'https://www.littler.com/es/news-analysis/asap/mexico-tiene-nueva-ley-en-materia-de-proteccion-de-datos-personales', 'https://aws.amazon.com/financial-services/security-compliance/compliance-center/mx', 'https://www.ixopay.com/reports-and-guides/ixopay-pci-dss-v401-shared-responsibility-matrix', 'https://services.google.com/fh/files/misc/gcp_pci_dss_v4_responsibility_matrix.pdf']::text[]),
  ('OBJ-37', 'migracion', 'No podemos parar', array['No podemos parar', 'Si se cae el sistema, se para la planta']::text[], null, array['¿Qué procesos no pueden detenerse ni un minuto?', '¿Cuánto tiempo sin sistema sería tolerable, siendo realistas?', '¿Hay fechas que debamos evitar, como cierre o temporada alta?']::text[], 'Normalmente se planea por etapas, empezando por algo no crítico y con plan de regreso.', array['Cero downtime garantizado', 'Es un fin de semana y listo']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-38', 'migracion', '¿Cuánto tiempo estaremos sin servicio?', array['¿Cuánto tiempo estaremos sin servicio?']::text[], null, array['¿Qué sistemas le preocupa que se detengan primero?', 'En la última actualización grande, ¿cuánto tiempo estuvieron fuera?']::text[], 'No le quiero dar un número sin ver su ambiente; el especialista le da una estimación por escrito.', array['Cualquier cifra de horas o minutos no validada']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-39', 'migracion', 'Tenemos sistemas viejos sin documentación', array['Tenemos sistemas viejos sin documentación', 'El que lo hizo ya no trabaja aquí']::text[], null, array['¿Qué sistemas dependen de ese aplicativo?', '¿Quién lo mantiene hoy, aunque sea informalmente?', '¿Les serviría empezar con un diagnóstico?']::text[], 'Es más común de lo que parece; el primer paso suele ser un levantamiento de qué depende de qué.', array['Eso se migra igual que todo']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-40', 'migracion', 'No tenemos gente para migrar', array['No tenemos gente para migrar']::text[], null, array['¿Qué parte de una migración les preocupa más?', '¿Qué ventana de mantenimiento podrían usar?']::text[], 'La migración la llevamos nosotros, con fecha de corte y operación en paralelo; su equipo valida.', array['Es facilísimo', 'No se va a notar nada']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-41', 'migracion', '¿Se conecta con mi SAP / CONTPAQi / ERP hecho en casa?', array['¿Se conecta con mi SAP / CONTPAQi / ERP hecho en casa?']::text[], null, array['¿Qué sistema y qué versión usan?', '¿Qué información necesita moverse y cada cuánto?', '¿Quién administra hoy ese sistema?']::text[], 'Anoto el sistema y la versión exactos para que el especialista confirme cómo se integra.', array['Se conecta con todo', 'Es plug and play']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-42', 'migracion', 'Luego no me puedo salir', array['Luego no me puedo salir']::text[], null, array['¿Qué le pasó con el proveedor anterior al querer salirse?', 'Si se fuera, ¿en qué formato necesitaría sus datos?']::text[], 'Revisemos juntos las condiciones de salida y de exportación antes de firmar.', array['Se pueden ir cuando quieran sin costo, salvo que el contrato lo diga']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-43', 'migracion', '¿Dónde quedan mis datos?', array['¿Dónde quedan mis datos?', '¿Se van a Estados Unidos?']::text[], null, array['¿Tienen alguna obligación de mantener datos en México?', '¿Les importa más la ubicación del dato o quién puede accederlo?']::text[], 'Hoy hay regiones de nube en México; la ubicación exacta depende del servicio y se confirma por escrito.', array['Sus datos nunca salen de México']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[]),
  ('OBJ-44', 'migracion', 'Todos dicen 99.9% y luego se cae', array['Todos dicen 99.9% y luego se cae']::text[], null, array['¿Qué pasó con su proveedor actual cuando se cayó?', '¿Qué le importa más: disponibilidad, tiempo de respuesta o compensación?']::text[], 'Tiene razón en desconfiar del número solo. Revisemos qué mide el SLA, qué excluye y qué pasa si no se cumple.', array['Nunca se cae', 'un porcentaje distinto al del contrato']::text[], false, array['https://anadea.info/blog/cloud-migration-services/', 'https://www.qovery.com/blog/phased-hybrid-cloud-migration-plan-without-downtime', 'https://cloud.nl/en/knowledge-base/cloud-migration/minimising-downtime-migration/', 'https://www.gorelo.io/?p=12415', 'https://www.buchanan.com/hubfs/downloads-resources/2026_msp-evaluation-checklist.pdf', 'https://aws.amazon.com/blogs/aws/now-open-aws-mexico-central-region']::text[])
