-- Banco de objeciones del Traductor (objeciones/objeciones.json, del reporte «Manejo de objeciones en ventas»).
-- En vivo, el agente reconoce la objeción del cliente y el servidor toma de aquí la pregunta que se le sugiere al
-- vendedor, con su «Di mejor» y lo que no debe decir. El texto lo pone la base, no el modelo.
-- Mismo acceso que la memoria: solo el servidor con la API key de administrador; RLS sin políticas.

create table public.objeciones (
  id text primary key,
  categoria text not null check (categoria in ('autoridad', 'contrato', 'evasiva', 'migracion', 'necesidad', 'precio', 'proveedor', 'regulacion', 'seguridad', 'timing')),
  objecion text not null,
  variantes text[] not null default '{}',
  -- Qué suele haber detrás de la objeción, para el brief y para el modelo.
  detras text,
  -- Preguntas para el vendedor, en orden de preferencia; se sugiere la primera que no se haya usado en la llamada.
  preguntas text[] not null check (cardinality(preguntas) > 0),
  di_mejor text not null,
  no_decir text[] not null default '{}',
  -- Regulación: frases que deben pasar por revisión legal antes de usarse con clientes.
  revisar_legal boolean not null default false,
  fuentes text[] not null default '{}',
  activa boolean not null default true,
  actualizado timestamptz not null default now()
);

-- Cada pregunta de objeción que el Traductor sugirió en una llamada: así no se repite y se puede ver qué funciona.
create table public.objeciones_llamada (
  id bigint generated always as identity primary key,
  llamada_id uuid not null references public.llamadas (id) on delete cascade,
  objecion_id text not null references public.objeciones (id),
  pregunta text not null,
  creado timestamptz not null default now(),
  unique (llamada_id, objecion_id, pregunta)
);

create index on public.objeciones_llamada (objecion_id);

alter table public.objeciones enable row level security;
alter table public.objeciones_llamada enable row level security;
revoke all on public.objeciones, public.objeciones_llamada from anon, authenticated;

on conflict (id) do update set
  categoria = excluded.categoria, objecion = excluded.objecion, variantes = excluded.variantes, detras = excluded.detras,
  preguntas = excluded.preguntas, di_mejor = excluded.di_mejor, no_decir = excluded.no_decir,
  revisar_legal = excluded.revisar_legal, fuentes = excluded.fuentes, actualizado = now();
